var EXPORT_FILES = {
  "settings.py": "\"\"\"Settings for the three-round maze-solving game.\"\"\"\n\nSCREEN_WIDTH = 1040\nSCREEN_HEIGHT = 700\nFPS = 60\n# TODO 1 [Required]: Name your game.\n# The current text is only an example chosen for this starter project.\n# Modify the strings below so players can understand your own game.\n# Keep quotation marks around every text value.\n#\n# Tip: MISSION_RULES / HOW_TO_PLAY_RULES are a separate Bonus TODO near the\n# end of this file (TODO 9) - write those once your game (custom item(s),\n# map) is actually finished, so the rules you write are true.\n\n# --- TODO 1: WRITE YOUR CODE BELOW ---\nTITLE = \"Maze Runner\"  # Modify this title to match your game.\nGAME_SUBTITLE = \"Solve the maze before time runs out\"\n# --- END OF TODO 1 ---\n\n\nMAZE_OFFSET_X = 32\nMAZE_OFFSET_Y = 126\n\nSHOW_DFS_GENERATION = True\nDFS_STEPS_PER_FRAME = 8\n\nWHITE = (255, 255, 255)\nBLACK = (25, 25, 25)\nBACKGROUND_COLOR = (241, 245, 249)\nWALL_COLOR = (30, 41, 59)\nVISITED_COLOR = (186, 230, 253)\nCURRENT_CELL_COLOR = (251, 191, 36)\nPATH_COLOR = (139, 92, 246)\nPLAYER_COLOR = (37, 99, 235)\nGOAL_COLOR = (250, 204, 21)\nBOMB_COLOR = (15, 23, 42)\nBOMB_EXPLOSION_COLOR = (239, 68, 68)\n\n# Professional UI palette\nNAVY = (15, 23, 42)\nSLATE = (71, 85, 105)\nMUTED = (100, 116, 139)\nPANEL_COLOR = (255, 255, 255)\nPANEL_BORDER = (226, 232, 240)\nACCENT = (79, 70, 229)\nACCENT_LIGHT = (238, 242, 255)\nSUCCESS = (22, 163, 74)\nWARNING = (245, 158, 11)\nDANGER = (220, 38, 38)\n\nPLAYER_MOVE_DELAY_MS = 100\n\nALLOW_PATH_HINT = True\nMAX_HINT_COUNT = 2\n\n# =========================================================\n# Route weights for the Hint button's Dijkstra route\n# =========================================================\n# The Hint button finds the shortest route from the player to the goal\n# that AVOIDS active bombs. Students may freely use negative, zero, or\n# positive values here.\n# Example:\n# Normal: 0    -> a standard cell\n# Bomb: 1000   -> a cell the route should strongly avoid\n# Before Dijkstra runs, the same offset is added to every weight\n# so that the smallest adjusted weight becomes 1.\nSTUDENT_NORMAL_WEIGHT = 0\nSTUDENT_BOMB_WEIGHT = 1000\n\n# Configuration for each round\n# Round 2 uses the original game difficulty.\n# TODO 6 [Bonus]: Redesign the three rounds.\n# Detailed hint:\n# You may change rows, cols, object counts, extra_open_walls, and time_limit_seconds.\n# Keep every dictionary key and keep all values as integers.\n# Smaller rows and cols make an easier round.\n\n# --- TODO 6: WRITE YOUR CODE BELOW ---\nROUND_CONFIGS = [\n    {\n        \"rows\": 11,\n        \"cols\": 15,\n        \"cell_size\": 38,\n        \"extra_open_walls\": 5,\n        \"bomb_count\": 2,\n        \"custom_item_count\": 2,\n        \"time_limit_seconds\": 70,\n    },\n    {\n        \"rows\": 15,\n        \"cols\": 21,\n        \"cell_size\": 30,\n        \"extra_open_walls\": 6,\n        \"bomb_count\": 4,\n        \"custom_item_count\": 3,\n        \"time_limit_seconds\": 55,\n    },\n    {\n        \"rows\": 17,\n        \"cols\": 25,\n        \"cell_size\": 25,\n        \"extra_open_walls\": 8,\n        \"bomb_count\": 6,\n        \"custom_item_count\": 4,\n        \"time_limit_seconds\": 45,\n    },\n]\n# --- END OF TODO 6 ---\n\n# Use the built-in shape when an image path is None.\n# TODO 7 [Bonus] (Part 1/2): Replace the player, goal, item, or bomb images.\n# Detailed hint:\n# Several ready-to-use images are provided in assets/images/ so you can pick\n# among them, or supply your own. Put an image file path in quotation marks,\n# such as \"assets/images/player_1.png\". Keep None to use the built-in fallback drawing.\n# You may change any number of the four lines below.\n\n# --- TODO 7 (Part 1/2): WRITE YOUR CODE BELOW ---\nPLAYER_IMAGE_PATH = None  # Example: \"assets/images/boy.png\" (also try lion.png, duck.png, player_ninja.png, player_robot.png)\nGOAL_IMAGE_PATH = None  # Example: \"assets/images/house.png\" (also try goal_flag.png, goal_door.png, goal_chest.png)\nBOMB_IMAGE_PATH = None  # Example: \"assets/images/bomb.png\" (also try bomb_2.png)\nFLOOR_TILE_IMAGE_PATH = None  # Background floor for open path cells. Example: \"assets/images/floor_tile_1.png\" (also try floor_tile_2.png)\n# --- END OF TODO 7 (Part 1/2) ---\nBOMB_EXPLOSION_IMAGE_PATH = \"assets/images/explode_2.png\"  # also try explode.png\nBOMB_EXPLOSION_DURATION_MS = 500\n\n# TODO 7 [Bonus] (Part 2/2): Add background music and a bomb sound effect.\n# Detailed hint:\n# A ready-to-use sound effect and a background music loop are provided in\n# assets/sounds/ so you can pick among them, or supply your own.\n# Keep a value as None to run the game without that sound.\n\n# --- TODO 7 (Part 2/2): WRITE YOUR CODE BELOW ---\nBOMB_SOUND_PATH = None  # Example: \"assets/sounds/explosion_1.wav\" (also try explosion_2.wav, explosion_3.wav)\nBACKGROUND_MUSIC_PATH = None  # Example: \"assets/sounds/bgm_1.wav\" (also try bgm_2.wav)\n# --- END OF TODO 7 (Part 2/2) ---\nBACKGROUND_MUSIC_VOLUME = 0.25\nCUSTOM_ITEM_IMAGE_PATH = \"assets/images/item_star.png\"  # used for every entry in CUSTOM_ITEMS below\nCUSTOM_ITEM_SOUND_PATH = \"assets/sounds/pickup_3.wav\"\n\n# =========================================================\n# Customize your collectible item(s) below.\n# =========================================================\n# TODO 8 [Bonus]: Design your own collectible item(s).\n# Detailed hint:\n# CUSTOM_ITEMS is a list - add as many dictionaries as you like, each with\n# its own name, RGB color, an \"effect\" (what happens when it's collected),\n# and an \"amount\" (how much of that effect).\n#   effect=\"add_time\"  -> amount is EXTRA SECONDS added to the round's clock.\n#   effect=\"add_hint\"  -> amount is EXTRA HINT USES added to hints_remaining.\n# Every round spawns custom_item_count items total, each one randomly\n# drawn from this list, so several distinct items can appear side by side.\n# Feel free to invent your own effect name too (e.g. \"shrink_maze\") - the\n# game simply does nothing extra for an effect it doesn't recognize, so\n# an experimental effect never crashes anything; it just won't do anything\n# until someone wires it up in game.py.\n# Keep the same dictionary keys (name/color/effect/amount) so the rest of\n# the game continues to work.\n\n# --- TODO 8: WRITE YOUR CODE BELOW ---\nCUSTOM_ITEMS = [\n    {\n        \"name\": \"Custom Item\",\n        \"color\": (180, 180, 180),\n        \"effect\": \"add_time\",\n        \"amount\": 0,\n    },\n]\n# --- END OF TODO 8 ---\n\n# =========================================================\n# Write your game's rules below (Bonus capstone - unlocks once every other\n# Bonus challenge is completed or skipped, since the rules only make sense\n# once your game - custom item(s), map - actually exists).\n# =========================================================\n# TODO 9 [Bonus]: Write your game's rules.\n# Detailed hint:\n# MISSION_RULES and HOW_TO_PLAY_RULES are lists of short strings shown on\n# the mission and how-to-play screens. Write them to match the game you\n# actually built - your custom item(s), your map.\n\n# --- TODO 9: WRITE YOUR CODE BELOW ---\nMISSION_RULES = [\n    \"Reach the goal before time runs out.\",\n]\nHOW_TO_PLAY_RULES = [\n    \"Reach the goal to clear each round.\",\n    \"Move with the Arrow Keys or WASD.\",\n    \"Bombs send you back to the start - avoid them.\",\n    \"Collect items for a helpful bonus effect.\",\n]\n# --- END OF TODO 9 ---\n",
  "game.py": "import random\n\nimport pygame\n\nfrom settings import (\n    SCREEN_WIDTH,\n    SCREEN_HEIGHT,\n    FPS,\n    TITLE,\n    GAME_SUBTITLE,\n    MISSION_RULES,\n    HOW_TO_PLAY_RULES,\n    BACKGROUND_COLOR,\n    BLACK,\n    WHITE,\n    SHOW_DFS_GENERATION,\n    DFS_STEPS_PER_FRAME,\n    PLAYER_MOVE_DELAY_MS,\n    ALLOW_PATH_HINT,\n    MAX_HINT_COUNT,\n    ROUND_CONFIGS,\n    BOMB_SOUND_PATH,\n    BACKGROUND_MUSIC_PATH,\n    BACKGROUND_MUSIC_VOLUME,\n    CUSTOM_ITEM_SOUND_PATH,\n    CUSTOM_ITEMS,\n    STUDENT_NORMAL_WEIGHT,\n    STUDENT_BOMB_WEIGHT,\n    NAVY,\n    SLATE,\n    MUTED,\n    PANEL_COLOR,\n    PANEL_BORDER,\n    ACCENT,\n    ACCENT_LIGHT,\n    SUCCESS,\n    WARNING,\n    DANGER,\n    MAZE_OFFSET_X,\n    MAZE_OFFSET_Y,\n)\nfrom maze import Maze\nfrom player import Player\nfrom goal import Goal\nfrom items import CustomItem, Bomb, create_random_positions\nfrom pathfinding import find_path_dijkstra\n\n\ndef _lerp_color(c1, c2, t):\n    return tuple(int(c1[i] + (c2[i] - c1[i]) * t) for i in range(3))\n\n\ndef draw_vertical_gradient(surface, rect, top_color, bottom_color):\n    \"\"\"Fill rect with a smooth top-to-bottom color gradient.\"\"\"\n    height = max(1, rect.height)\n    band = pygame.Surface((rect.width, height))\n    for y in range(height):\n        color = _lerp_color(top_color, bottom_color, y / height)\n        pygame.draw.line(band, color, (0, y), (rect.width, y))\n    surface.blit(band, rect.topleft)\n\n\ndef draw_radial_glow(surface, center, radius, color, max_alpha=90):\n    \"\"\"Draw a soft radial glow by layering translucent circles.\"\"\"\n    glow = pygame.Surface((radius * 2, radius * 2), pygame.SRCALPHA)\n    steps = 10\n    for i in range(steps, 0, -1):\n        t = i / steps\n        r = int(radius * t)\n        alpha = int(max_alpha * (1 - t) ** 2)\n        pygame.draw.circle(glow, (*color, alpha), (radius, radius), r)\n    surface.blit(glow, (center[0] - radius, center[1] - radius), special_flags=pygame.BLEND_RGBA_ADD)\n\n\ndef draw_soft_shadow(surface, rect, radius=16, spread=14, max_alpha=50):\n    \"\"\"UI drop shadows are disabled. This function intentionally does nothing.\"\"\"\n    return\n\n\nclass Game:\n    def __init__(self):\n        pygame.init()\n\n        self.screen = pygame.display.set_mode((SCREEN_WIDTH, SCREEN_HEIGHT))\n        pygame.display.set_caption(TITLE)\n\n        self.clock = pygame.time.Clock()\n        self.font = pygame.font.SysFont(\"arial\", 22)\n        self.small_font = pygame.font.SysFont(\"arial\", 17)\n        self.tiny_font = pygame.font.SysFont(\"arial\", 15)\n        self.medium_font = pygame.font.SysFont(\"arial\", 28, bold=True)\n        self.big_font = pygame.font.SysFont(\"arial\", 42, bold=True)\n        self.hero_font = pygame.font.SysFont(\"arial\", 58, bold=True)\n\n        self.bomb_sound = self.load_sound(BOMB_SOUND_PATH)\n        self.custom_item_sound = self.load_sound(CUSTOM_ITEM_SOUND_PATH)\n        self.load_background_music()\n\n        self.running = True\n        self.screen_state = \"start\"\n        self.ui_buttons = []\n\n        self.current_round = 0\n        self.game_clear = False\n        self.round_failed = False\n        self.failure_reason = \"\"\n        self.round_transition_time = None\n\n        self.load_round()\n\n    def load_sound(self, path):\n        if path is None:\n            return None\n\n        try:\n            if not pygame.mixer.get_init():\n                pygame.mixer.init()\n            return pygame.mixer.Sound(path)\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Sound effect load failed: {error}\")\n            return None\n\n    def load_background_music(self):\n        if BACKGROUND_MUSIC_PATH is None:\n            return\n        try:\n            if not pygame.mixer.get_init():\n                pygame.mixer.init()\n            pygame.mixer.music.load(BACKGROUND_MUSIC_PATH)\n            pygame.mixer.music.set_volume(BACKGROUND_MUSIC_VOLUME)\n            pygame.mixer.music.play(-1)\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Background music load failed: {error}\")\n\n    def load_round(self):\n        self.config = ROUND_CONFIGS[self.current_round]\n\n        self.maze = Maze(self.config)\n        if not SHOW_DFS_GENERATION:\n            self.maze.generate_all()\n\n        self.player = Player(self.config[\"cell_size\"])\n        self.goal = Goal(\n            self.config[\"rows\"],\n            self.config[\"cols\"],\n            self.config[\"cell_size\"],\n        )\n\n        self.items = []\n        self.bombs = []\n        self.objects_created = False\n\n        self.hints_remaining = MAX_HINT_COUNT\n        self.bonus_time_seconds = 0\n        self.start_time = None\n        self.last_player_move_time = 0\n\n        self.game_clear = False\n        self.round_failed = False\n        self.failure_reason = \"\"\n        self.round_transition_time = None\n\n    def start_game(self):\n        self.current_round = 0\n        self.load_round()\n        self.screen_state = \"playing\"\n\n    def restart_game(self):\n        self.current_round = 0\n        self.load_round()\n        self.screen_state = \"playing\"\n\n    def quit_game(self):\n        self.running = False\n\n    def create_game_objects(self):\n        forbidden = {\n            self.player.get_position(),\n            self.goal.get_position(),\n        }\n\n        custom_positions = create_random_positions(\n            self.config[\"rows\"], self.config[\"cols\"],\n            self.config.get(\"custom_item_count\", 0), forbidden,\n        )\n        self.items = [\n            CustomItem(row, col, self.config[\"cell_size\"], random.choice(CUSTOM_ITEMS))\n            for row, col in custom_positions\n        ]\n        forbidden.update(custom_positions)\n\n        bomb_positions = create_random_positions(\n            self.config[\"rows\"],\n            self.config[\"cols\"],\n            self.config[\"bomb_count\"],\n            forbidden,\n        )\n        self.bombs = [\n            Bomb(row, col, self.config[\"cell_size\"])\n            for row, col in bomb_positions\n        ]\n        forbidden.update(bomb_positions)\n\n        self.objects_created = True\n        self.start_time = pygame.time.get_ticks()\n\n    # =========================================================\n    # 1. EVENT HANDLING\n    # =========================================================\n    def handle_events(self):\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                self.running = False\n\n            elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:\n                self.handle_mouse_click(event.pos)\n\n            elif event.type == pygame.KEYDOWN:\n                if self.screen_state == \"start\":\n                    if event.key in (pygame.K_RETURN, pygame.K_SPACE):\n                        self.start_game()\n                    elif event.key == pygame.K_ESCAPE:\n                        self.running = False\n                    continue\n\n                if event.key == pygame.K_ESCAPE:\n                    self.running = False\n\n                elif event.key == pygame.K_r:\n                    self.restart_game()\n\n                elif event.key in (pygame.K_RETURN, pygame.K_SPACE):\n                    if self.round_failed or self.game_clear:\n                        self.restart_game()\n\n                elif (\n                    event.key == pygame.K_h\n                    and ALLOW_PATH_HINT\n                    and self.maze.generation_complete\n                    and not self.game_clear\n                    and not self.round_failed\n                ):\n                    self.show_player_hint()\n\n    def handle_mouse_click(self, position):\n        for button in reversed(self.ui_buttons):\n            if button[\"enabled\"] and button[\"rect\"].collidepoint(position):\n                button[\"action\"]()\n                break\n\n    # =========================================================\n    # 2. UPDATE LOGIC\n    # =========================================================\n    def update(self):\n        if self.screen_state != \"playing\":\n            return\n\n        if self.round_transition_time is not None:\n            elapsed = pygame.time.get_ticks() - self.round_transition_time\n            if elapsed >= 900:\n                self.current_round += 1\n                self.load_round()\n            return\n\n        if self.game_clear or self.round_failed:\n            return\n\n        if not self.maze.generation_complete:\n            for _ in range(DFS_STEPS_PER_FRAME):\n                self.maze.generate_step()\n                if self.maze.generation_complete:\n                    break\n            return\n\n        if not self.objects_created:\n            self.create_game_objects()\n\n        self.update_player()\n        self.update_bombs()\n        self.check_items()\n        self.check_bombs()\n        self.check_goal()\n        self.check_time_limit()\n\n    def update_player(self):\n        now = pygame.time.get_ticks()\n        if now - self.last_player_move_time < PLAYER_MOVE_DELAY_MS:\n            return\n\n        keys = pygame.key.get_pressed()\n        moved = False\n\n        # TODO 2 [Required]: Connect the arrow keys or WASD keys to maze movement.\n        # This is the grid-movement version of Reach the Star TODO 2's\n        # if/elif key-dispatch pattern.\n        # Recall the same key checks you used there:\n        # Left/A, Right/D, Up/W, and Down/S.\n        # Here, instead of changing velocity, call self.player.try_move(direction, self.maze)\n        # and store the result in moved, the same way the line below is written:\n        # moved = self.player.try_move(\"left\", self.maze)\n        # Only the direction string changes for each key (see the hints below).\n        # Keep the first condition as if and the remaining conditions as elif,\n        # so the player moves only one maze cell at a time.\n\n        # --- TODO 2: WRITE YOUR CODE BELOW ---\n        if keys[pygame.K_LEFT] or keys[pygame.K_a]:\n            pass  # Write your code here. Hint: the direction string is \"left\"\n        elif keys[pygame.K_RIGHT] or keys[pygame.K_d]:\n            pass  # Write your code here. Hint: the direction string is \"right\"\n        elif keys[pygame.K_UP] or keys[pygame.K_w]:\n            pass  # Write your code here. Hint: the direction string is \"top\"\n        elif keys[pygame.K_DOWN] or keys[pygame.K_s]:\n            pass  # Write your code here. Hint: the direction string is \"bottom\"\n        # --- END OF TODO 2 ---\n\n        if moved:\n            self.last_player_move_time = now\n            self.maze.clear_path_display()\n\n    def update_bombs(self):\n        now = pygame.time.get_ticks()\n        for bomb in self.bombs:\n            bomb.update(now)\n\n    def check_items(self):\n        player_position = self.player.get_position()\n        for item in self.items:\n            if item.active and item.get_position() == player_position:\n                item.active = False\n                self.apply_custom_item_effect(item.item_def)\n                if self.custom_item_sound:\n                    self.custom_item_sound.play()\n\n    def apply_custom_item_effect(self, item_def):\n        \"\"\"Given (not a TODO): applies whatever \"effect\"/\"amount\" a custom\n        item (TODO 8) declares. Only \"add_time\" and \"add_hint\" are wired up\n        - any other effect string a student invents is a safe no-op here\n        (it just doesn't do anything extra yet), matching TODO 8's promise\n        that an experimental effect never crashes the game.\"\"\"\n        effect = item_def.get(\"effect\")\n        amount = item_def.get(\"amount\", 0)\n        if effect == \"add_time\":\n            self.bonus_time_seconds += amount\n        elif effect == \"add_hint\":\n            self.hints_remaining += amount\n\n    def check_bombs(self):\n        now = pygame.time.get_ticks()\n        player_position = self.player.get_position()\n\n        for bomb in self.bombs:\n            if bomb.state == \"ACTIVE\" and bomb.get_position() == player_position:\n                if bomb.trigger(now):\n                    self.player.reset_position()\n                    self.maze.clear_path_display()\n                    if self.bomb_sound:\n                        self.bomb_sound.play()\n                break\n\n    def check_goal(self):\n        if self.player.get_position() != self.goal.get_position():\n            return\n\n        if self.current_round == len(ROUND_CONFIGS) - 1:\n            self.game_clear = True\n        else:\n            self.round_transition_time = pygame.time.get_ticks()\n\n    def check_time_limit(self):\n        if self.start_time is None:\n            return\n        if self.get_remaining_time() <= 0:\n            self.round_failed = True\n            self.failure_reason = \"ROUND FAILED: Time limit exceeded.\"\n\n    def get_remaining_time(self):\n        limit = self.config[\"time_limit_seconds\"] + self.bonus_time_seconds\n        if self.start_time is None:\n            return limit\n\n        elapsed = (pygame.time.get_ticks() - self.start_time) // 1000\n        return max(0, limit - elapsed)\n\n    def get_current_route_weight(self, position):\n        active_bomb_positions = {\n            bomb.get_position()\n            for bomb in self.bombs\n            if bomb.state == \"ACTIVE\"\n        }\n        if position in active_bomb_positions:\n            return STUDENT_BOMB_WEIGHT\n        return STUDENT_NORMAL_WEIGHT\n\n    def show_player_hint(self):\n        if self.hints_remaining <= 0:\n            return\n\n        student_weights = [STUDENT_NORMAL_WEIGHT, STUDENT_BOMB_WEIGHT]\n\n        path = find_path_dijkstra(\n            self.maze,\n            self.player.get_position(),\n            self.goal.get_position(),\n            get_weight=self.get_current_route_weight,\n            all_weights=student_weights,\n        )\n\n        if path:\n            self.maze.show_path(path)\n            self.hints_remaining -= 1\n\n    # =========================================================\n    # 3. RENDER / DRAW\n    # =========================================================\n    def draw(self):\n        self.screen.fill(BACKGROUND_COLOR)\n        self.ui_buttons = []\n\n        if self.screen_state == \"start\":\n            self.draw_start_screen()\n            pygame.display.flip()\n            return\n\n        self.draw_header()\n        self.draw_maze_panel()\n        self.draw_side_panel()\n        self.draw_footer()\n\n        self.maze.draw(self.screen)\n\n        if self.maze.generation_complete:\n            for item in self.items:\n                item.draw(self.screen)\n            for bomb in self.bombs:\n                bomb.draw(self.screen)\n            self.goal.draw(self.screen)\n            self.player.draw(self.screen)\n\n        if not self.maze.generation_complete:\n            self.ui_buttons = []\n            self.draw_status_modal(\n                \"CREATING MAZE\",\n                \"DFS is building a new maze...\",\n                ACCENT,\n            )\n        elif self.round_transition_time is not None:\n            self.ui_buttons = []\n            self.draw_status_modal(\n                f\"ROUND {self.current_round + 1} CLEAR\",\n                \"Preparing the next challenge\",\n                SUCCESS,\n            )\n        elif self.round_failed:\n            self.ui_buttons = []\n            self.draw_status_modal(\n                \"ROUND FAILED\",\n                \"The time limit has expired.\",\n                DANGER,\n                help_text=\"Try again from Round 1.\",\n                buttons=[\n                    (\"Restart\", self.restart_game, \"primary\"),\n                    (\"Quit\", self.quit_game, \"secondary\"),\n                ],\n            )\n        elif self.game_clear:\n            self.ui_buttons = []\n            self.draw_status_modal(\n                \"MISSION COMPLETE\",\n                \"All 3 rounds cleared!\",\n                SUCCESS,\n                help_text=\"Great job, Maze Runner!\",\n                buttons=[\n                    (\"Play Again\", self.restart_game, \"primary\"),\n                    (\"Quit\", self.quit_game, \"secondary\"),\n                ],\n            )\n\n        pygame.display.flip()\n\n    def draw_rounded_panel(\n        self,\n        rect,\n        color=PANEL_COLOR,\n        border=PANEL_BORDER,\n        radius=16,\n        shadow=True,\n    ):\n        if shadow:\n            draw_soft_shadow(self.screen, rect, radius=radius, spread=12, max_alpha=45)\n\n        panel = pygame.Surface(rect.size, pygame.SRCALPHA)\n        draw_vertical_gradient(\n            panel,\n            pygame.Rect(0, 0, *rect.size),\n            _lerp_color(color, (255, 255, 255), 0.35),\n            color,\n        )\n        mask = pygame.Surface(rect.size, pygame.SRCALPHA)\n        pygame.draw.rect(mask, (255, 255, 255, 255), (0, 0, *rect.size), border_radius=radius)\n        panel.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)\n\n        self.screen.blit(panel, rect.topleft)\n        pygame.draw.rect(self.screen, border, rect, width=1, border_radius=radius)\n\n    def draw_button(self, rect, text, action, style=\"primary\", enabled=True):\n        mouse_pos = pygame.mouse.get_pos()\n        hovered = enabled and rect.collidepoint(mouse_pos)\n\n        styles = {\n            \"primary\": {\n                \"fill\": ACCENT,\n                \"fill_hover\": (99, 102, 241),\n                \"border\": ACCENT,\n                \"text\": WHITE,\n            },\n            \"secondary\": {\n                \"fill\": PANEL_COLOR,\n                \"fill_hover\": (248, 250, 252),\n                \"border\": PANEL_BORDER,\n                \"text\": NAVY,\n            },\n            \"success\": {\n                \"fill\": SUCCESS,\n                \"fill_hover\": (34, 197, 94),\n                \"border\": SUCCESS,\n                \"text\": WHITE,\n            },\n            \"danger\": {\n                \"fill\": DANGER,\n                \"fill_hover\": (239, 68, 68),\n                \"border\": DANGER,\n                \"text\": WHITE,\n            },\n        }\n        palette = styles.get(style, styles[\"primary\"])\n\n        fill = palette[\"fill_hover\"] if hovered else palette[\"fill\"]\n        border = palette[\"border\"]\n        text_color = palette[\"text\"]\n\n        if not enabled:\n            fill = (226, 232, 240)\n            border = (203, 213, 225)\n            text_color = (148, 163, 184)\n\n        draw_soft_shadow(\n            self.screen, rect, radius=14, spread=10,\n            max_alpha=60 if hovered else 42,\n        )\n\n        button = pygame.Surface(rect.size, pygame.SRCALPHA)\n        draw_vertical_gradient(\n            button,\n            pygame.Rect(0, 0, *rect.size),\n            _lerp_color(fill, (255, 255, 255), 0.22),\n            _lerp_color(fill, (0, 0, 0), 0.08),\n        )\n        mask = pygame.Surface(rect.size, pygame.SRCALPHA)\n        pygame.draw.rect(mask, (255, 255, 255, 255), (0, 0, *rect.size), border_radius=14)\n        button.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)\n        self.screen.blit(button, (rect.x, rect.y - (2 if hovered else 0)))\n\n        draw_rect = rect.move(0, -2 if hovered else 0)\n        pygame.draw.rect(self.screen, border, draw_rect, width=1, border_radius=14)\n        if hovered and enabled:\n            glow = pygame.Surface((rect.width + 6, rect.height + 6), pygame.SRCALPHA)\n            pygame.draw.rect(glow, (*fill, 60), glow.get_rect(), width=3, border_radius=16)\n            self.screen.blit(glow, (draw_rect.x - 3, draw_rect.y - 3))\n\n        label = self.small_font.render(text, True, text_color)\n        self.screen.blit(label, label.get_rect(center=draw_rect.center))\n\n        self.ui_buttons.append(\n            {\n                \"rect\": rect,\n                \"action\": action,\n                \"enabled\": enabled,\n            }\n        )\n\n    def draw_header(self):\n        header = pygame.Rect(0, 0, SCREEN_WIDTH, 98)\n        draw_vertical_gradient(self.screen, header, (23, 33, 61), NAVY)\n        for i in range(4):\n            alpha = 70 - i * 15\n            band = pygame.Surface((SCREEN_WIDTH, 1), pygame.SRCALPHA)\n            band.fill((*ACCENT, max(alpha, 0)))\n            self.screen.blit(band, (0, 94 + i))\n\n        title = self.medium_font.render(TITLE.upper(), True, WHITE)\n        subtitle = self.small_font.render(\n            GAME_SUBTITLE,\n            True,\n            (203, 213, 225),\n        )\n        self.screen.blit(title, (32, 20))\n        self.screen.blit(subtitle, (33, 57))\n\n        cards = [\n            (\"ROUND\", f\"{self.current_round + 1} / {len(ROUND_CONFIGS)}\", ACCENT),\n            (\n                \"TIME\",\n                f\"{self.get_remaining_time()}s\",\n                DANGER if self.get_remaining_time() <= 10 else ACCENT,\n            ),\n            (\"HINTS\", f\"{self.hints_remaining} / {MAX_HINT_COUNT}\", ACCENT),\n        ]\n        x = 560\n        for label, value, color in cards:\n            rect = pygame.Rect(x, 16, 124, 64)\n            card = pygame.Surface(rect.size, pygame.SRCALPHA)\n            draw_vertical_gradient(card, pygame.Rect(0, 0, *rect.size), (38, 51, 73), (26, 36, 54))\n            mask = pygame.Surface(rect.size, pygame.SRCALPHA)\n            pygame.draw.rect(mask, (255, 255, 255, 255), (0, 0, *rect.size), border_radius=12)\n            card.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)\n            self.screen.blit(card, rect.topleft)\n            pygame.draw.rect(self.screen, (*color, 90), rect, width=1, border_radius=12)\n            self.screen.blit(\n                self.tiny_font.render(label, True, (148, 163, 184)),\n                (x + 14, 25),\n            )\n            self.screen.blit(self.font.render(value, True, color), (x + 14, 47))\n            x += 136\n\n    def draw_maze_panel(self):\n        maze_width = self.config[\"cols\"] * self.config[\"cell_size\"]\n        maze_height = self.config[\"rows\"] * self.config[\"cell_size\"]\n        rect = pygame.Rect(\n            MAZE_OFFSET_X - 14,\n            MAZE_OFFSET_Y - 14,\n            maze_width + 28,\n            maze_height + 28,\n        )\n        self.draw_rounded_panel(rect, radius=18)\n\n    def draw_side_panel(self):\n        panel = pygame.Rect(704, 118, 304, 486)\n        self.draw_rounded_panel(panel, radius=18)\n\n        self.screen.blit(self.medium_font.render(\"Mission\", True, NAVY), (728, 140))\n        mission_lines = MISSION_RULES\n        y = 181\n        for line in mission_lines:\n            self.screen.blit(self.small_font.render(line, True, SLATE), (728, y))\n            y += 24\n\n        pygame.draw.line(self.screen, PANEL_BORDER, (728, 238), (984, 238), 1)\n        self.screen.blit(self.font.render(\"Game Elements\", True, NAVY), (728, 258))\n\n        # This list drives the \"Game Elements\" legend panel. BOMB and GOAL\n        # describe the fixed Required game rules and are provided for you.\n        # You may freely edit any of the label text here as much as you like.\n        first_custom_item = CUSTOM_ITEMS[0] if CUSTOM_ITEMS else None\n        if first_custom_item:\n            effect = first_custom_item.get(\"effect\")\n            amount = first_custom_item.get(\"amount\", 0)\n            if effect == \"add_time\":\n                custom_item_detail = f\"+{amount}s time\"\n            elif effect == \"add_hint\":\n                custom_item_detail = f\"+{amount} hint use(s)\"\n            else:\n                custom_item_detail = f\"effect: {effect}\"\n            if len(CUSTOM_ITEMS) > 1:\n                custom_item_detail += f\" (+{len(CUSTOM_ITEMS) - 1} more)\"\n        else:\n            custom_item_detail = \"None configured\"\n        elements = [\n            (\"CUSTOM_ITEM\", first_custom_item[\"color\"] if first_custom_item else ACCENT, first_custom_item[\"name\"] if first_custom_item else \"Custom Item\", custom_item_detail),\n            (\"BOMB\", (30, 41, 59), \"Bomb\", \"Return to start\"),\n            (\"GOAL\", (250, 204, 21), \"Goal\", \"Finish the round\"),\n        ]\n        y = 300\n        for element_type, color, name, detail in elements:\n            icon_rect = pygame.Rect(733, y - 2, 22, 22)\n            if element_type == \"CUSTOM_ITEM\" and first_custom_item:\n                CustomItem(0, 0, 30, first_custom_item).draw_icon(self.screen, icon_rect)\n            elif element_type == \"BOMB\":\n                pygame.draw.circle(self.screen, color, icon_rect.center, 8)\n                pygame.draw.circle(\n                    self.screen,\n                    WHITE,\n                    (icon_rect.centerx + 4, icon_rect.centery - 4),\n                    2,\n                )\n            else:\n                pygame.draw.rect(self.screen, color, icon_rect, border_radius=6)\n\n            self.screen.blit(self.small_font.render(name, True, NAVY), (760, y))\n            detail_surface = self.tiny_font.render(detail, True, MUTED)\n            self.screen.blit(\n                detail_surface,\n                (984 - detail_surface.get_width(), y + 2),\n            )\n            y += 30\n\n        pygame.draw.line(self.screen, PANEL_BORDER, (728, 492), (984, 492), 1)\n        self.screen.blit(self.font.render(\"Hint Route\", True, NAVY), (728, 508))\n        hint_box = pygame.Rect(728, 540, 256, 42)\n        pygame.draw.rect(self.screen, ACCENT_LIGHT, hint_box, border_radius=12)\n        key_rect = pygame.Rect(740, 546, 30, 28)\n        pygame.draw.rect(self.screen, ACCENT, key_rect, border_radius=8)\n        key = self.small_font.render(\"H\", True, WHITE)\n        self.screen.blit(key, key.get_rect(center=key_rect.center))\n        self.screen.blit(\n            self.small_font.render(\"Show Dijkstra route\", True, ACCENT),\n            (782, 551),\n        )\n\n    def draw_footer(self):\n        footer = pygame.Rect(0, 628, SCREEN_WIDTH, 72)\n        pygame.draw.rect(self.screen, (248, 250, 252), footer)\n        pygame.draw.line(self.screen, PANEL_BORDER, (0, 628), (SCREEN_WIDTH, 628), 1)\n\n        controls = [\n            (\"MOVE\", \"Arrow Keys / WASD\"),\n            (\"RESTART\", \"R\"),\n            (\"QUIT\", \"ESC\"),\n        ]\n        x = 32\n        for label, key in controls:\n            self.screen.blit(self.tiny_font.render(label, True, MUTED), (x, 646))\n            key_surface = self.small_font.render(key, True, NAVY)\n            self.screen.blit(key_surface, (x, 666))\n            x += 215\n\n        status = \"MAZE READY\" if self.maze.generation_complete else \"GENERATING\"\n        dot_color = SUCCESS if self.maze.generation_complete else WARNING\n        pygame.draw.circle(self.screen, dot_color, (608, 663), 5)\n        status_surface = self.small_font.render(status, True, SLATE)\n        self.screen.blit(status_surface, (621, 654))\n\n        hint_enabled = (\n            ALLOW_PATH_HINT\n            and self.maze.generation_complete\n            and not self.game_clear\n            and not self.round_failed\n            and self.hints_remaining > 0\n        )\n        self.draw_button(\n            pygame.Rect(700, 644, 110, 40),\n            \"Hint\",\n            self.show_player_hint,\n            style=\"primary\",\n            enabled=hint_enabled,\n        )\n        self.draw_button(\n            pygame.Rect(824, 644, 110, 40),\n            \"Restart\",\n            self.restart_game,\n            style=\"secondary\",\n            enabled=True,\n        )\n        self.draw_button(\n            pygame.Rect(948, 644, 72, 40),\n            \"Quit\",\n            self.quit_game,\n            style=\"secondary\",\n            enabled=True,\n        )\n\n    def draw_overlay(self):\n        overlay = pygame.Surface((SCREEN_WIDTH, SCREEN_HEIGHT), pygame.SRCALPHA)\n        overlay.fill((15, 23, 42, 168))\n        self.screen.blit(overlay, (0, 0))\n\n    def draw_status_modal(\n        self,\n        title,\n        subtitle,\n        accent_color,\n        help_text=None,\n        buttons=None,\n    ):\n        self.draw_overlay()\n        modal_height = 280 if buttons else 210\n        modal = pygame.Rect(250, 210, 540, modal_height)\n        self.draw_rounded_panel(\n            modal,\n            color=PANEL_COLOR,\n            border=(255, 255, 255),\n            radius=22,\n            shadow=True,\n        )\n        pygame.draw.rect(\n            self.screen,\n            accent_color,\n            (modal.x, modal.y, 8, modal.height),\n            border_radius=4,\n        )\n\n        icon_center = (modal.centerx, modal.y + 52)\n        pygame.draw.circle(self.screen, (*accent_color, 35), icon_center, 24)\n        pygame.draw.circle(self.screen, accent_color, icon_center, 8)\n\n        title_surface = self.big_font.render(title, True, NAVY)\n        self.screen.blit(\n            title_surface,\n            title_surface.get_rect(center=(modal.centerx, modal.y + 112)),\n        )\n\n        subtitle_surface = self.font.render(subtitle, True, SLATE)\n        self.screen.blit(\n            subtitle_surface,\n            subtitle_surface.get_rect(center=(modal.centerx, modal.y + 154)),\n        )\n\n        if help_text:\n            info_rect = pygame.Rect(modal.x + 82, modal.y + 176, modal.width - 164, 34)\n            pygame.draw.rect(self.screen, ACCENT_LIGHT, info_rect, border_radius=10)\n            info_surface = self.small_font.render(help_text, True, ACCENT)\n            self.screen.blit(info_surface, info_surface.get_rect(center=info_rect.center))\n\n        if buttons:\n            total_width = len(buttons) * 132 - 12\n            start_x = modal.centerx - total_width // 2\n            y = modal.bottom - 58\n            for index, (label, action, style) in enumerate(buttons):\n                rect = pygame.Rect(start_x + index * 132, y, 120, 42)\n                self.draw_button(rect, label, action, style=style, enabled=True)\n\n    def draw_start_screen(self):\n        draw_vertical_gradient(\n            self.screen,\n            pygame.Rect(0, 0, SCREEN_WIDTH, SCREEN_HEIGHT),\n            (241, 245, 249),\n            (226, 232, 240),\n        )\n\n        hero = pygame.Rect(0, 0, SCREEN_WIDTH, 220)\n        draw_vertical_gradient(self.screen, hero, (17, 26, 51), (10, 16, 36))\n        draw_radial_glow(self.screen, (920, 90), 170, (79, 70, 229), max_alpha=110)\n        draw_radial_glow(self.screen, (990, 10), 110, (56, 189, 248), max_alpha=70)\n        draw_radial_glow(self.screen, (860, 190), 130, (139, 92, 246), max_alpha=90)\n\n        self.screen.blit(\n            self.small_font.render(\"PYGAME MAZE PROJECT\", True, (191, 219, 254)),\n            (52, 48),\n        )\n        title = self.hero_font.render(TITLE.upper(), True, WHITE)\n        self.screen.blit(title, (48, 78))\n        subtitle = self.small_font.render(\n            \"Navigate a maze and complete all 3 rounds before time runs out.\",\n            True,\n            (226, 232, 240),\n        )\n        self.screen.blit(subtitle, (52, 146))\n\n        main_panel = pygame.Rect(44, 198, 610, 430)\n        side_panel = pygame.Rect(680, 198, 316, 430)\n        self.draw_rounded_panel(main_panel, radius=24)\n        self.draw_rounded_panel(side_panel, radius=24)\n\n        self.screen.blit(self.medium_font.render(\"How to Play\", True, NAVY), (72, 230))\n        # Keep only the information players need to start and finish the game.\n        bullets = HOW_TO_PLAY_RULES\n        y = 278\n        for line in bullets:\n            pygame.draw.circle(self.screen, ACCENT, (80, y + 8), 4)\n            self.screen.blit(self.small_font.render(line, True, SLATE), (96, y))\n            y += 29\n\n        chip_y = 510\n        chips = [\n            \"3 Rounds\",\n            \"Keyboard + Buttons\",\n            \"Weighted Pathfinding\",\n        ]\n        chip_x = 70\n        for chip in chips:\n            chip_surface = self.small_font.render(chip, True, ACCENT)\n            chip_rect = pygame.Rect(chip_x, chip_y, chip_surface.get_width() + 28, 34)\n            pygame.draw.rect(self.screen, ACCENT_LIGHT, chip_rect, border_radius=17)\n            pygame.draw.rect(self.screen, (199, 210, 254), chip_rect, width=1, border_radius=17)\n            self.screen.blit(chip_surface, (chip_rect.x + 14, chip_rect.y + 8))\n            chip_x += chip_rect.width + 12\n\n        self.screen.blit(self.font.render(\"Start Game\", True, NAVY), (72, 566))\n        self.screen.blit(\n            self.small_font.render(\"You can click the buttons or press Enter.\", True, MUTED),\n            (72, 592),\n        )\n        self.draw_button(\n            pygame.Rect(390, 556, 150, 48),\n            \"Start\",\n            self.start_game,\n            style=\"primary\",\n            enabled=True,\n        )\n        self.draw_button(\n            pygame.Rect(552, 556, 90, 48),\n            \"Quit\",\n            self.quit_game,\n            style=\"secondary\",\n            enabled=True,\n        )\n\n        self.screen.blit(self.medium_font.render(\"Quick Controls\", True, NAVY), (708, 230))\n        control_cards = [\n            (\"Move\", \"Arrow Keys / WASD\"),\n            (\"Hint\", \"H or Hint Button\"),\n            (\"Restart\", \"R or Restart Button\"),\n            (\"Quit\", \"ESC or Quit Button\"),\n        ]\n        y = 278\n        for label, value in control_cards:\n            card = pygame.Rect(706, y, 264, 64)\n            pygame.draw.rect(self.screen, (248, 250, 252), card, border_radius=14)\n            pygame.draw.rect(self.screen, PANEL_BORDER, card, width=1, border_radius=14)\n            self.screen.blit(self.tiny_font.render(label.upper(), True, MUTED), (724, y + 12))\n            self.screen.blit(self.small_font.render(value, True, NAVY), (724, y + 34))\n            y += 76\n\n        footer_note = self.tiny_font.render(\n            \"Tip: Hints show the current best Dijkstra path.\",\n            True,\n            MUTED,\n        )\n        self.screen.blit(footer_note, (708, 588))\n\n    # =========================================================\n    # STANDARD GAME LOOP\n    # =========================================================\n    def run(self):\n        while self.running:\n            self.handle_events()\n            self.update()\n            self.draw()\n            self.clock.tick(FPS)\n\n        pygame.quit()\n",
  "player.py": "import pygame\n\nfrom settings import MAZE_OFFSET_X, MAZE_OFFSET_Y, PLAYER_COLOR, PLAYER_IMAGE_PATH\n\n\nclass Player:\n    _images = {}\n\n    def __init__(self, cell_size, row=0, col=0):\n        self.cell_size = cell_size\n        self.row = row\n        self.col = col\n\n    @classmethod\n    def get_image(cls, cell_size):\n        if cell_size in cls._images:\n            return cls._images[cell_size]\n        if PLAYER_IMAGE_PATH is None:\n            cls._images[cell_size] = None\n            return None\n        try:\n            image = pygame.image.load(PLAYER_IMAGE_PATH).convert_alpha()\n            image = pygame.transform.scale(image, (cell_size - 10, cell_size - 10))\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Player image load failed: {error}\")\n            image = None\n        cls._images[cell_size] = image\n        return image\n\n    def get_position(self):\n        return self.row, self.col\n\n    def reset_position(self):\n        self.row = 0\n        self.col = 0\n\n    def try_move(self, direction, maze):\n        current = maze.get_cell(self.row, self.col)\n        # TODO 3 [Required]: Stop movement when there is no cell or a wall blocks the direction.\n        # Detailed hint:\n        # current can be None, and current.walls[direction] is True when a wall exists.\n        # Join the two conditions with or, then return False inside the if block.\n\n        # --- TODO 3: WRITE YOUR CODE BELOW ---\n        pass  # Write your code here.\n        # --- END OF TODO 3 ---\n        dr, dc = {\n            \"top\": (-1, 0),\n            \"right\": (0, 1),\n            \"bottom\": (1, 0),\n            \"left\": (0, -1),\n        }[direction]\n        # TODO 4 [Required]: Update the player's row and column.\n        # Detailed hint:\n        # dr is the row change and dc is the column change.\n        # Add dr to self.row and dc to self.col with +=.\n\n        # --- TODO 4: WRITE YOUR CODE BELOW ---\n        pass  # Write your code here.\n        # --- END OF TODO 4 ---\n        return True\n\n    def get_rect(self):\n        return pygame.Rect(\n            MAZE_OFFSET_X + self.col * self.cell_size + 5,\n            MAZE_OFFSET_Y + self.row * self.cell_size + 5,\n            self.cell_size - 10,\n            self.cell_size - 10,\n        )\n\n    def draw(self, screen):\n        rect = self.get_rect()\n        image = self.get_image(self.cell_size)\n        if image:\n            screen.blit(image, rect)\n        else:\n            pygame.draw.circle(screen, PLAYER_COLOR, rect.center, max(5, (self.cell_size - 12) // 2))\n",
  "maze.py": "import random\n\nfrom cell import Cell\nfrom settings import STUDENT_NORMAL_WEIGHT\n\n\nclass Maze:\n    def __init__(self, config):\n        self.rows = config[\"rows\"]\n        self.cols = config[\"cols\"]\n        self.cell_size = config[\"cell_size\"]\n        self.extra_open_walls = config[\"extra_open_walls\"]\n\n        self.grid = [\n            [Cell(r, c, self.cell_size) for c in range(self.cols)]\n            for r in range(self.rows)\n        ]\n        self.stack = []\n        self.current = self.grid[0][0]\n        self.current.visited = True\n        self.current.is_current = True\n        self.generation_complete = False\n        self.post_processing_complete = False\n\n    def get_cell(self, row, col):\n        if 0 <= row < self.rows and 0 <= col < self.cols:\n            return self.grid[row][col]\n        return None\n\n    def get_unvisited_neighbors(self, cell):\n        candidates = [\n            (\"top\", cell.row - 1, cell.col),\n            (\"right\", cell.row, cell.col + 1),\n            (\"bottom\", cell.row + 1, cell.col),\n            (\"left\", cell.row, cell.col - 1),\n        ]\n        return [\n            (direction, neighbor)\n            for direction, row, col in candidates\n            if (neighbor := self.get_cell(row, col)) is not None\n            and not neighbor.visited\n        ]\n\n    def remove_wall_between(self, current, next_cell, direction):\n        opposite = {\n            \"top\": \"bottom\",\n            \"right\": \"left\",\n            \"bottom\": \"top\",\n            \"left\": \"right\",\n        }\n        current.walls[direction] = False\n        next_cell.walls[opposite[direction]] = False\n\n    def generate_step(self):\n        if self.generation_complete:\n            return\n\n        neighbors = self.get_unvisited_neighbors(self.current)\n        if neighbors:\n            # Given (not a TODO): randomized depth-first-search maze\n            # generation. This algorithm (random.choice + stack-based\n            # backtracking) isn't reinforced by anything else this project\n            # teaches, so it ships as working code - see\n            # TEACHER_TODO_GUIDE.md for why. Bonus TODO 6's map editor lets\n            # you design your own layout without needing this algorithm.\n            direction, next_cell = random.choice(neighbors)\n            self.current.is_current = False\n            self.stack.append(self.current)  # Given: push the current cell so we can backtrack to it later.\n            self.remove_wall_between(self.current, next_cell, direction)\n            self.current = next_cell\n            self.current.visited = True\n            self.current.is_current = True\n        elif self.stack:\n            self.current.is_current = False\n            self.current = self.stack.pop()  # Given: backtrack to the most recently saved cell.\n            self.current.is_current = True\n        else:\n            self.current.is_current = False\n            self.generation_complete = True\n            self.finish_generation()\n\n    def generate_all(self):\n        while not self.generation_complete:\n            self.generate_step()\n\n    def finish_generation(self):\n        if self.post_processing_complete:\n            return\n        self.open_extra_walls(self.extra_open_walls)\n        self.post_processing_complete = True\n\n    def open_extra_walls(self, count):\n        candidates = []\n        for row in range(self.rows):\n            for col in range(self.cols):\n                cell = self.grid[row][col]\n                if col + 1 < self.cols and cell.walls[\"right\"]:\n                    candidates.append((cell, self.grid[row][col + 1], \"right\"))\n                if row + 1 < self.rows and cell.walls[\"bottom\"]:\n                    candidates.append((cell, self.grid[row + 1][col], \"bottom\"))\n        random.shuffle(candidates)\n        for current, neighbor, direction in candidates[:count]:\n            self.remove_wall_between(current, neighbor, direction)\n\n    def get_terrain(self, position):\n        # Given (not a TODO): terrain is always \"NORMAL\" now - swamp/custom\n        # terrain were removed along with scoring (see TEACHER_TODO_GUIDE.md).\n        # get_terrain() is kept as a stable method name in case a future\n        # extension reintroduces terrain types.\n        return \"NORMAL\"\n\n    def get_route_weight(self, position):\n        return STUDENT_NORMAL_WEIGHT\n\n    def get_open_neighbors(self, position):\n        row, col = position\n        cell = self.get_cell(row, col)\n        if cell is None:\n            return []\n        directions = [\n            (\"top\", -1, 0),\n            (\"right\", 0, 1),\n            (\"bottom\", 1, 0),\n            (\"left\", 0, -1),\n        ]\n        result = []\n        for direction, dr, dc in directions:\n            if not cell.walls[direction]:\n                neighbor = self.get_cell(row + dr, col + dc)\n                if neighbor:\n                    result.append((neighbor.row, neighbor.col))\n        return result\n\n    def clear_path_display(self):\n        for row in self.grid:\n            for cell in row:\n                cell.is_path = False\n\n    def show_path(self, path):\n        self.clear_path_display()\n        for row, col in path:\n            cell = self.get_cell(row, col)\n            if cell:\n                cell.is_path = True\n\n    def draw(self, screen):\n        for row in self.grid:\n            for cell in row:\n                cell.draw(screen, show_generation=not self.generation_complete)\n",
  "pathfinding.py": "import heapq\n\n\ndef find_path_dijkstra(\n    map_data,\n    start,\n    end,\n    get_weight=None,\n    all_weights=None,\n):\n    \"\"\"\n    This Dijkstra implementation supports student-defined negative weights.\n    It has one job in the finished game: the player's \"Hint\" button calls\n    it (with the real bomb-avoidance weights from settings.py) to find the\n    shortest safe route from the player to the goal.\n\n    1. Students choose weights freely, such as -100, 0, and 100.\n    2. The smallest weight is identified.\n    3. The same offset is added to every weight so the smallest value becomes 1.\n    4. Dijkstra runs using the adjusted positive weights.\n\n    Example:\n        Original weights: -100, 0, 100, 1000\n        Minimum value: -100\n        Offset: 1 - (-100) = 101\n        Adjusted weights: 1, 101, 201, 1101\n\n    NOTE: heapq.heappop() (the priority-queue pop) is already written for\n    you below, along with a \"visited\" set that guarantees this function\n    always finishes even if the TODO below is left blank, so an unfinished\n    Required TODO can never freeze the game.\n    \"\"\"\n    if get_weight is None:\n        get_weight = map_data.get_route_weight\n\n    if all_weights is None:\n        all_weights = [0]\n\n    minimum_weight = min(all_weights)\n    weight_shift = 1 - minimum_weight\n\n    def get_positive_weight(position):\n        original_weight = get_weight(position)\n        return original_weight + weight_shift\n\n    queue = [(0, start)]\n    distance = {start: 0}\n    parent = {start: None}\n    visited = set()  # Given: guarantees Dijkstra always terminates safely.\n\n    while queue:\n        cost, current = heapq.heappop(queue)  # Given: take the lowest-cost entry out of the queue.\n\n        if current in visited:\n            continue  # Given: this entry is a stale duplicate, skip it.\n        visited.add(current)  # Given: this position is now finalized.\n\n        if current == end:\n            break\n\n        for neighbor in map_data.get_open_neighbors(current):\n            if neighbor in visited:\n                continue\n            step_cost = get_positive_weight(neighbor)\n\n            if step_cost <= 0:\n                raise ValueError(\n                    \"Adjusted Dijkstra weight must be positive.\"\n                )\n\n            # TODO 5 [Required] (Part 1/2): Calculate the candidate\n            # cost of reaching this neighbor through the current cell.\n            # Detailed hint:\n            # Add the cost already spent reaching current (cost) to this\n            # one extra step (step_cost).\n\n            # --- TODO 5 (Part 1/2): WRITE YOUR CODE BELOW ---\n            new_cost = 0  # Write your code here.\n            # --- END OF TODO 5 (Part 1/2) ---\n\n            # TODO 5 [Required] (Part 2/2): Decide whether new_cost\n            # is actually an improvement, and if so, record it and explore it.\n            # Detailed hint:\n            # Only keep new_cost if neighbor hasn't been seen yet, or if\n            # new_cost beats the recorded distance[neighbor]. When it is an\n            # improvement, update distance[neighbor] AND parent[neighbor]\n            # together (the cost and the route both changed), then push the\n            # improved (new_cost, neighbor) onto the queue so the search\n            # actually follows this better route.\n\n            # --- TODO 5 (Part 2/2): WRITE YOUR CODE BELOW ---\n            pass  # Write your code here.\n            # --- END OF TODO 5 (Part 2/2) ---\n\n    return reconstruct_path(parent, end)\n\n\ndef reconstruct_path(parent, end):\n    if end not in parent:\n        return []\n    path = []\n    current = end\n    while current is not None:\n        path.append(current)\n        current = parent[current]\n    path.reverse()\n    return path\n",
  "cell.py": "import pygame\n\nfrom settings import (\n    MAZE_OFFSET_X,\n    MAZE_OFFSET_Y,\n    WALL_COLOR,\n    VISITED_COLOR,\n    CURRENT_CELL_COLOR,\n    PATH_COLOR,\n    FLOOR_TILE_IMAGE_PATH,\n)\n\n\nclass Cell:\n    _floor_images = {}\n\n    def __init__(self, row, col, cell_size):\n        self.row = row\n        self.col = col\n        self.cell_size = cell_size\n        self.visited = False\n        self.is_current = False\n        self.is_path = False\n        self.terrain = \"NORMAL\"\n        self.walls = {\n            \"top\": True,\n            \"right\": True,\n            \"bottom\": True,\n            \"left\": True,\n        }\n\n    @classmethod\n    def get_floor_image(cls, cell_size):\n        if cell_size in cls._floor_images:\n            return cls._floor_images[cell_size]\n        if FLOOR_TILE_IMAGE_PATH is None:\n            cls._floor_images[cell_size] = None\n            return None\n        try:\n            image = pygame.image.load(FLOOR_TILE_IMAGE_PATH).convert_alpha()\n            image = pygame.transform.scale(image, (cell_size, cell_size))\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Floor image load failed: {error}\")\n            image = None\n        cls._floor_images[cell_size] = image\n        return image\n\n    def get_rect(self):\n        return pygame.Rect(\n            MAZE_OFFSET_X + self.col * self.cell_size,\n            MAZE_OFFSET_Y + self.row * self.cell_size,\n            self.cell_size,\n            self.cell_size,\n        )\n\n    def draw(self, screen, show_generation=False):\n        rect = self.get_rect()\n\n        floor_image = self.get_floor_image(self.cell_size)\n        if floor_image:\n            screen.blit(floor_image, rect)\n\n        if self.is_path:\n            overlay = pygame.Surface((self.cell_size, self.cell_size), pygame.SRCALPHA)\n            overlay.fill((*PATH_COLOR, 155))\n            screen.blit(overlay, rect)\n            pygame.draw.circle(screen, PATH_COLOR, rect.center, max(3, self.cell_size // 7))\n        elif self.is_current:\n            pygame.draw.rect(screen, CURRENT_CELL_COLOR, rect)\n        elif self.visited and show_generation:\n            overlay = pygame.Surface((self.cell_size, self.cell_size), pygame.SRCALPHA)\n            overlay.fill((*VISITED_COLOR, 110))\n            screen.blit(overlay, rect)\n\n        x, y, s = rect.x, rect.y, self.cell_size\n        if self.walls[\"top\"]:\n            pygame.draw.line(screen, WALL_COLOR, (x, y), (x + s, y), 3)\n        if self.walls[\"right\"]:\n            pygame.draw.line(screen, WALL_COLOR, (x + s, y), (x + s, y + s), 3)\n        if self.walls[\"bottom\"]:\n            pygame.draw.line(screen, WALL_COLOR, (x, y + s), (x + s, y + s), 3)\n        if self.walls[\"left\"]:\n            pygame.draw.line(screen, WALL_COLOR, (x, y), (x, y + s), 3)\n",
  "goal.py": "import pygame\n\nfrom settings import MAZE_OFFSET_X, MAZE_OFFSET_Y, GOAL_COLOR, GOAL_IMAGE_PATH\n\n\nclass Goal:\n    _images = {}\n\n    def __init__(self, rows, cols, cell_size):\n        self.row = rows - 1\n        self.col = cols - 1\n        self.cell_size = cell_size\n\n    @classmethod\n    def get_image(cls, cell_size):\n        if cell_size in cls._images:\n            return cls._images[cell_size]\n        if GOAL_IMAGE_PATH is None:\n            cls._images[cell_size] = None\n            return None\n        try:\n            image = pygame.image.load(GOAL_IMAGE_PATH).convert_alpha()\n            image = pygame.transform.scale(image, (cell_size - 8, cell_size - 8))\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Goal image load failed: {error}\")\n            image = None\n        cls._images[cell_size] = image\n        return image\n\n    def get_position(self):\n        return self.row, self.col\n\n    def get_rect(self):\n        return pygame.Rect(\n            MAZE_OFFSET_X + self.col * self.cell_size + 4,\n            MAZE_OFFSET_Y + self.row * self.cell_size + 4,\n            self.cell_size - 8,\n            self.cell_size - 8,\n        )\n\n    def draw(self, screen):\n        rect = self.get_rect()\n        image = self.get_image(self.cell_size)\n        if image:\n            screen.blit(image, rect)\n        else:\n            pygame.draw.rect(screen, GOAL_COLOR, rect, border_radius=max(3, self.cell_size // 5))\n",
  "items.py": "import random\nimport pygame\n\nfrom settings import (\n    MAZE_OFFSET_X,\n    MAZE_OFFSET_Y,\n    BOMB_COLOR,\n    BOMB_EXPLOSION_COLOR,\n    BOMB_IMAGE_PATH,\n    BOMB_EXPLOSION_IMAGE_PATH,\n    BOMB_EXPLOSION_DURATION_MS,\n    CUSTOM_ITEM_IMAGE_PATH,\n)\n\n\nclass Collectible:\n    \"\"\"Base drawing/position logic shared by every pickup in the maze.\n    The only pickup that actually spawns is CustomItem below (each with its\n    own name/color/effect/amount from settings.CUSTOM_ITEMS) - this base\n    class just factors out the generic \"draw a glossy gem\" fallback so\n    CustomItem doesn't have to repeat it.\"\"\"\n\n    _images = {}\n\n    def __init__(self, row, col, cell_size):\n        self.row = row\n        self.col = col\n        self.cell_size = cell_size\n        self.active = True\n\n    def get_position(self):\n        return self.row, self.col\n\n    def get_rect(self):\n        return pygame.Rect(\n            MAZE_OFFSET_X + self.col * self.cell_size + 4,\n            MAZE_OFFSET_Y + self.row * self.cell_size + 4,\n            self.cell_size - 8,\n            self.cell_size - 8,\n        )\n\n    def draw_collectible(self, screen, rect, color=(34, 197, 94)):\n        \"\"\"Prettier fallback item: a glossy gem with a sparkle.\"\"\"\n        shadow = pygame.Surface((rect.width + 8, rect.height + 8), pygame.SRCALPHA)\n        pygame.draw.ellipse(\n            shadow,\n            (15, 23, 42, 35),\n            (2, rect.height - 2, rect.width, max(6, rect.height // 4)),\n        )\n        screen.blit(shadow, (rect.x - 4, rect.y - 4))\n\n        cx, cy = rect.center\n        w = rect.width\n        h = rect.height\n        gem_points = [\n            (cx, rect.y + max(1, h // 10)),\n            (rect.right - max(2, w // 5), cy),\n            (cx, rect.bottom - max(1, h // 10)),\n            (rect.x + max(2, w // 5), cy),\n        ]\n\n        outline = (6, 95, 70)\n        main = color\n        light = (134, 239, 172)\n        highlight = (220, 252, 231)\n\n        pygame.draw.polygon(screen, outline, gem_points)\n        inner_points = [\n            (cx, rect.y + max(3, h // 7)),\n            (rect.right - max(4, w // 4), cy),\n            (cx, rect.bottom - max(3, h // 7)),\n            (rect.x + max(4, w // 4), cy),\n        ]\n        pygame.draw.polygon(screen, main, inner_points)\n\n        top_triangle = [\n            (cx, rect.y + max(3, h // 7)),\n            (rect.right - max(5, w // 3), cy - max(1, h // 8)),\n            (rect.x + max(5, w // 3), cy - max(1, h // 8)),\n        ]\n        pygame.draw.polygon(screen, light, top_triangle)\n\n        facet_line_y = cy\n        pygame.draw.line(screen, outline, (cx, rect.y + max(2, h // 8)), (cx, rect.bottom - max(2, h // 8)), 1)\n        pygame.draw.line(screen, outline, (rect.x + max(4, w // 4), facet_line_y), (rect.right - max(4, w // 4), facet_line_y), 1)\n\n        sparkle_radius = max(1, rect.width // 10)\n        sparkle_center = (rect.x + max(6, w // 3), rect.y + max(5, h // 3))\n        pygame.draw.circle(screen, highlight, sparkle_center, sparkle_radius)\n        pygame.draw.line(screen, highlight, (sparkle_center[0] - sparkle_radius * 2, sparkle_center[1]), (sparkle_center[0] + sparkle_radius * 2, sparkle_center[1]), 1)\n        pygame.draw.line(screen, highlight, (sparkle_center[0], sparkle_center[1] - sparkle_radius * 2), (sparkle_center[0], sparkle_center[1] + sparkle_radius * 2), 1)\n\n    def draw_icon(self, screen, rect):\n        self.draw_collectible(screen, rect)\n\n    def draw(self, screen):\n        if not self.active:\n            return\n        self.draw_icon(screen, self.get_rect())\n\n\nclass CustomItem(Collectible):\n    \"\"\"A collectible drawn from settings.CUSTOM_ITEMS.\n\n    `item_def` is one entry of that list (a dict with name/color/effect/\n    amount) - each spawned CustomItem remembers which entry it is, so\n    several distinct items can appear in the same round with their own\n    color and effect. \"effect\" is \"add_time\" (amount = extra seconds) or\n    \"add_hint\" (amount = extra hint uses) - see Game.apply_custom_item_effect\n    in game.py for where that's actually applied.\n    \"\"\"\n\n    _custom_images = {}\n\n    def __init__(self, row, col, cell_size, item_def):\n        super().__init__(row, col, cell_size)\n        self.item_def = item_def\n\n    @classmethod\n    def get_image(cls, cell_size):\n        if cell_size in cls._custom_images:\n            return cls._custom_images[cell_size]\n        if CUSTOM_ITEM_IMAGE_PATH is None:\n            cls._custom_images[cell_size] = None\n            return None\n        try:\n            image = pygame.image.load(CUSTOM_ITEM_IMAGE_PATH).convert_alpha()\n            image = pygame.transform.scale(image, (cell_size - 8, cell_size - 8))\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Custom item image load failed: {error}\")\n            image = None\n        cls._custom_images[cell_size] = image\n        return image\n\n    def draw_icon(self, screen, rect):\n        image = self.get_image(rect.width + 8)\n        if image:\n            screen.blit(image, image.get_rect(center=rect.center))\n        else:\n            self.draw_collectible(screen, rect)\n\n    def draw_collectible(self, screen, rect, color=None):\n        color = self.item_def.get(\"color\", (180, 180, 180))\n        pygame.draw.circle(screen, color, rect.center, max(5, rect.width // 3))\n        pygame.draw.circle(screen, (255, 255, 255), rect.center, max(2, rect.width // 8))\n\n\nclass Bomb:\n    _normal_images = {}\n    _explosion_images = {}\n\n    def __init__(self, row, col, cell_size):\n        self.row = row\n        self.col = col\n        self.cell_size = cell_size\n        self.state = \"ACTIVE\"\n        self.explosion_start_time = None\n\n    @classmethod\n    def load_image(cls, path, cell_size, explosion=False):\n        cache = cls._explosion_images if explosion else cls._normal_images\n        if cell_size in cache:\n            return cache[cell_size]\n        if path is None:\n            cache[cell_size] = None\n            return None\n        try:\n            image = pygame.image.load(path).convert_alpha()\n            image = pygame.transform.scale(image, (cell_size - 8, cell_size - 8))\n        except (pygame.error, FileNotFoundError, TypeError) as error:\n            print(f\"[Info] Bomb image load failed: {error}\")\n            image = None\n        cache[cell_size] = image\n        return image\n\n    def get_position(self):\n        return self.row, self.col\n\n    def get_rect(self):\n        return pygame.Rect(\n            MAZE_OFFSET_X + self.col * self.cell_size + 4,\n            MAZE_OFFSET_Y + self.row * self.cell_size + 4,\n            self.cell_size - 8,\n            self.cell_size - 8,\n        )\n\n    def trigger(self, current_time):\n        if self.state != \"ACTIVE\":\n            return False\n        self.state = \"EXPLODING\"\n        self.explosion_start_time = current_time\n        return True\n\n    def update(self, current_time):\n        if (\n            self.state == \"EXPLODING\"\n            and current_time - self.explosion_start_time >= BOMB_EXPLOSION_DURATION_MS\n        ):\n            self.state = \"INACTIVE\"\n\n    def draw(self, screen):\n        if self.state == \"INACTIVE\":\n            return\n\n        rect = self.get_rect()\n        if self.state == \"EXPLODING\":\n            image = self.load_image(BOMB_EXPLOSION_IMAGE_PATH, self.cell_size, explosion=True)\n            if image:\n                screen.blit(image, rect)\n            else:\n                pygame.draw.circle(screen, BOMB_EXPLOSION_COLOR, rect.center, max(5, self.cell_size // 3))\n            return\n\n        image = self.load_image(BOMB_IMAGE_PATH, self.cell_size, explosion=False)\n        if image:\n            screen.blit(image, rect)\n        else:\n            pygame.draw.circle(screen, BOMB_COLOR, rect.center, max(3, self.cell_size // 6))\n\n\ndef create_random_positions(rows, cols, count, forbidden):\n    candidates = [\n        (r, c)\n        for r in range(rows)\n        for c in range(cols)\n        if (r, c) not in forbidden\n    ]\n    random.shuffle(candidates)\n    return candidates[:count]\n",
  "main.py": "from game import Game\n\n\ndef main():\n    Game().run()\n\n\nif __name__ == \"__main__\":\n    main()\n",
  "requirements.txt": "pygame>=2.5.0\n"
};

